        raise ValueError("Invalid input. Input should be a non-empty string without spaces.")

    # Iterate through each character in the string
    for char in paren_string:
        # Move through open parentheses
        if char == '(':
            temp += char
        # Handle close parentheses
        elif char == ')':
            temp += char
            # Check if the sequence of parentheses is valid
