def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Example implementation using dynamic programming
    # This solution assumes each value can only be collected once and two paths are the same width
    # Complexity: O(N**2) if no frequent updates are expected
    if N == 0:
        return 0

    rows, cols = N, N
    dp = [[0] * cols for _ in range(rows)]

    # Copy the grid_values to the starting point
    for row, col, value in grid_values:
        if (row, col) == (0, 0):
            dp[row][col] = value
        elif row == 0:
            dp[row][col] = dp[row][col - 1] + value
        elif col == 0:
            dp[row][col] = dp[row - 1][col] + value
        else:
            dp[row][col] = max(dp[row][col - 1], dp[row - 1][col]) + value

    max_val_left = dp[N - 1][N - 1]  # Supplemental variable to handle cases when dp is not updated
    max_val_right = dp[N - 1][0]
    total_max_value = dp[N - 1][N - 1]

    # Iterate back from the bottom-right corner to potentially update the dp table again
    for row in range(N - 2, -1, -1):
        for col in range(N - 2, -1, -1):
            dp[row][col] = max(dp[row + 1][col], dp[row][col + 1]) + grid_values[row + 1][col][2]

    # Get the maximum sum of values on the left and right paths
    for row in range(N):
        for col in range(N - 2, -1, -1):
            if row == N - 1:
                max_val_right = max(max_val_right, dp[row][col])
            elif col == N - 1:
                max_val_left = max(max_val_left, dp[row][col])

    # Check for invalid input conditions
    if len(grid_values) == 0 or grid_values[-1] != (0, 0, 0):
        return "Invalid input grid values."

    return total_max_value + max_val_left + max_val_right

