def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")
    num = 2 * ((N - 1) // 3)
    denom = 4 * ((N + 2) // 3)

    if (N - 1) % 3 == 0:
        num ^= 1
        denom ^= 1

    return f"{num}/{denom}"

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or not isinstance(N, int) or not isinstance(K, int):
        raise ValueError("Invalid input")

    sorted_chars = sorted(num_str, reverse=True)
    sign_positions = []
    i = 0
    while i < K:
        sign_positions.append(i)
        i += 2

    for pos in sign_positions:
        if i + 1 <= N:
            sorted_chars[pos] = ((sorted_chars[pos - 1] if pos > 0 else 0) + sorted_chars[pos]) * sorted_chars[pos - 1] * sorted_chars[pos + 1]
            i += 2

    return int(''.join(sorted_chars[:N]))

