def verify_isbn(isbn: str) -> str:
    if not isbn:
        return "Invalid input"

    isbn = isbn.replace('-', '')
    if len(isbn) != 10 or isbn[9] not in '0123456789X':
        return "Invalid input"

    # Check isbn checksum
    total = 0
    multipliers = range(10, 0, -1)
    for i, digit in enumerate(isbn):
        if digit == 'X':
            digit = 10
        total += digit * multipliers[i]

    # Calculate check digit
    check_digit = 11 - (total % 11)
    if check_digit == 10:
        check_digit = 'X'

    if str(check_digit) == isbn[9]:
        return "Right"
    else:
        return isbn[:9] + str(check_digit)

