            max_separable = 0
            for col in optimal_cols:
                for row in optimal_rows:
                    separating_pairs = count_separating_pairs(optimal_rows, optimal_cols, chat_pairs)
                    if separating_pairs > max_separable:
                        max_separable = separating_pairs
                        optimal_rows = optimal_rows - set([row])
                    if len(optimal_rows) == 0:
                        break
            col_offset = len(optimal_cols) - len(optimal_rows)
            if optimal_cols:
                optimal_rows = optimal_rows.union({optimal_cols[col_offset]})
        return tuple(optimal_rows), tuple(optimal_cols)

