def max_energy(beads):
    n = len(beads)

    # Initialize a 2D array to store the maximum energy for sub-sequences
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if beads[i] == beads[j]:
                dp[i][j] = dp[i+1][j-1] + beads[i] ** 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    return dp[0][n-1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0:
        raise ValueError("Degree must be non-negative")

    polynomial = []
    for i, coeff in enumerate(reversed(coeffs)):
        if coeff == 0:
            continue
        degree = n - i
        if degree > 1:
            polynomial.append(f"{abs(coeff)}x^{degree}")
        elif degree > 0:
            if coeff < 0:
                polynomial.append("-x")
            else:
                polynomial.append("+x")
        else:
            if coeff == -1:
                polynomial.append("-1")
            else:
                polynomial.append(f"{ coeff}")
    if polynomial:
        return " + ".join(polynomial)[-1]
    return "0"

def decode(encoded: str, original: str, message: str) -> str:
    def build_mapping(encoded: str, original: str) -> dict:
        mapping = {}
        for en, or_ in zip(encoded, original):
            if en in mapping and mapping[en] != or_:
                return None  # Contradiction found
            mapping[en] = or_
        return mapping

    mapping = build_mapping(encoded, original)
    if mapping is None:
        return "Failed"  # Mapping generation failed

    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            return "Failed"  # Letter not represented in mapping

    return ''.join(decoded)

def largest_prime_factor(n: int) -> int:
    # Early return if 'n' is a prime number less than 4
    if n < 4:
        return n

    # Ensure 'n' is odd
    if n % 2 == 0:
        n //= 2

    # Iterate through odd factors starting from 3
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        # While 'i' is a factor of 'n', divide 'n' by 'i' and check if 'n' is prime
        while n % i == 0:
            n //= i

    # The remaining 'n' is a prime number greater than 2
    return n if n > 2 else 2

