def count_sequences(n: int, last: int, memo: dict) -> int:
    # Base cases
    if n > last // 2:
        return 0
    if n == 1:
        return 1
    if last == n:
        return 0  # Can't continue a sequence with itself

    # Check if the result is memoized
    if (n, last) in memo:
        return memo[(n, last)]

    # Recursive calculation
    count = 0
    for i in range(2, n + 1):
        if i <= last:
            count += count_sequences(i, n, memo)

    # Store the result in memoization
    memo[(n, last)] = count
    return count

