def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not all(char.isalpha() for char in key) or not all(char.isalpha() for char in ciphertext):
        raise ValueError("Key and ciphertext should only contain alphabetic characters.")

    key_length = len(key)
    plaintext = '')

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            shift = ord(key[i % key_length]) - ord('A') if char.isupper() else ord(key[i % key_length]) - ord('a')
            shifted_char = chr((ord(char) - shift - 65) % 26 + 65) if char.isupper() else chr((ord(char) - shift - 97) % 26 + 97)
            plaintext += shifted_char
        else:
            plaintext += char

    return plaintext

def mod_inverse(a, b):
    if b == 0:
        raise ValueError("Modulus must not be zero.")

    x0, x1, y0, y1 = 1, 0, 0, 1
    while a != 1:
        q = a // b
        a, b = b, a % b
        x0, x1 = x1 - q * x0, x0
        y0, y1 = y1 - q * y1, y1

    if x1 < 0:
        x1 += b

    return x1

